const COMPONENT_TYPES = ['rune'];

export function quote(items: Item[]): number {
  let base = 0;
  const componentCounts = new Map<string, number>();
  for (const item of items) {
    const premium = BASE_PREMIUMS[item.type];
    if (premium === undefined) {
      throw new Error(`unknown item type: ${item.type}`);
    }
    if (COMPONENT_TYPES.includes(item.type)) {
      componentCounts.set(item.type, (componentCounts.get(item.type) ?? 0) + 1);
      continue;
    }
    base += premium;
  }
  for (const [type, count] of componentCounts) {
    base += count === 3 ? 60 : count * BASE_PREMIUMS[type];
  }
  return base + 5;
}

