export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const COMPONENT_TYPES = ['rune', 'moonstone'];

export interface Customer {
  yearsWithMHPCO: number;
}

export function quote(
  items: Item[],
  customer: Customer = { yearsWithMHPCO: 0 },
  contractIndex = 0,
): number {
  let base = 0;
  let policyBase = 0;
  const componentCounts = new Map<string, number>();
  for (const item of items) {
    const premium = BASE_PREMIUMS[item.type];
    if (premium === undefined) {
      throw new Error(`unknown item type: ${item.type}`);
    }
    if (COMPONENT_TYPES.includes(item.type)) {
      componentCounts.set(item.type, (componentCounts.get(item.type) ?? 0) + 1);
      continue;
    }
    base += premium;
    policyBase += premium;
    if (item.cursed) {
      base += premium * 0.5;
    }
    if (item.enchantment !== undefined && item.enchantment >= 5) {
      base += premium * 0.3;
    }
  }
  for (const [type, count] of componentCounts) {
    const blockPremium = count === 3 ? 60 : count * BASE_PREMIUMS[type];
    base += blockPremium;
    policyBase += blockPremium;
  }
  if (customer.yearsWithMHPCO >= 2) {
    base -= policyBase * 0.2;
  }
  base += policyBase * 0.1;
  if (contractIndex > 0) {
    base -= policyBase * 0.15;
  }
  return Math.ceil(base + 5);
}

