import type { Item } from './quote.js';

export interface Policy {
  items: Item[];
  remainingCap?: number;
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

const DEDUCTIBLE = 100;

const INSURANCE_VALUES: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

export function settleClaim(policy: Policy, damages: Damage[]): ClaimResult {
  let payout = 0;
  const unclaimed = [...policy.items];
  for (const damage of damages) {
    if (damage.amount < 0) {
      throw new Error(`negative damage amount: ${damage.amount}`);
    }
    const index = unclaimed.findIndex((candidate) => candidate.type === damage.itemType);
    const item = index === -1 ? undefined : unclaimed.splice(index, 1)[0];
    if (item === undefined) {
      throw new Error(`item not covered by the policy: ${damage.itemType}`);
    }
    let reimbursed = damage.amount;
    if (item.enchantment !== undefined && item.enchantment >= 8) {
      reimbursed *= 0.5;
    }
    payout += reimbursed - DEDUCTIBLE;
  }
  if (policy.remainingCap === undefined) {
    const insuranceSum = policy.items.reduce(
      (sum, item) => sum + INSURANCE_VALUES[item.type],
      0,
    );
    policy.remainingCap = insuranceSum * 2;
  }
  const capped = Math.min(Math.floor(payout), policy.remainingCap);
  policy.remainingCap -= capped;
  return { payout: capped, remainingCap: policy.remainingCap };
}

